import { escapeAttribute, escapeText } from './html.js'
import { normalizeLabel } from './links.js'

const ESCAPABLE = '\\`*[]()'

/** The index of the first `]` that no backslash escapes, or -1. */
function closingBracket(text, from) {
  for (let index = from; index < text.length; index += 1) {
    if (text[index] === '\\') {
      index += 1
      continue
    }
    if (text[index] === ']') return index
  }
  return -1
}

/**
 * One link starting at `[`, inline or by reference, or undefined when nothing there is a link.
 * @param {string} text - the raw inline text.
 * @param {number} start - the index of the `[`.
 * @param {Map<string, {url: string}>} definitions - the definitions in force.
 * @returns {{url: string, inner: string, next: number}|undefined} the link.
 */
function readLink(text, start, definitions) {
  const close = closingBracket(text, start + 1)
  if (close === -1) return undefined
  const inner = text.slice(start + 1, close)
  if (text[close + 1] === '(') {
    const end = text.indexOf(')', close + 2)
    if (end === -1) return undefined
    return { url: text.slice(close + 2, end).trim(), inner, next: end + 1 }
  }
  if (text[close + 1] === '[') {
    const labelClose = closingBracket(text, close + 2)
    if (labelClose === -1) return undefined
    const written = text.slice(close + 2, labelClose)
    const definition = definitions.get(normalizeLabel(written === '' ? inner : written))
    if (definition === undefined) return undefined
    return { url: definition.url, inner, next: labelClose + 1 }
  }
  return undefined
}

/**
 * Render one run of inline Markdown.
 * @param {string} text - the raw inline text.
 * @param {Map<string, {url: string}>} [definitions] - the link definitions in force.
 * @returns {string} the HTML.
 */
export function renderInline(text, definitions = new Map()) {
  let out = ''
  let index = 0
  while (index < text.length) {
    const character = text[index]
    if (character === '\\' && index + 1 < text.length && ESCAPABLE.includes(text[index + 1])) {
      out += escapeText(text[index + 1])
      index += 2
      continue
    }
    if (character === '`') {
      const end = text.indexOf('`', index + 1)
      if (end !== -1) {
        out += `<code>${escapeText(text.slice(index + 1, end))}</code>`
        index = end + 1
        continue
      }
    }
    if (text.startsWith('**', index)) {
      const end = text.indexOf('**', index + 2)
      if (end !== -1) {
        out += `<strong>${renderInline(text.slice(index + 2, end), definitions)}</strong>`
        index = end + 2
        continue
      }
    }
    if (character === '*') {
      const end = text.indexOf('*', index + 1)
      if (end !== -1) {
        out += `<em>${renderInline(text.slice(index + 1, end), definitions)}</em>`
        index = end + 1
        continue
      }
    }
    if (character === '[') {
      const link = readLink(text, index, definitions)
      if (link !== undefined) {
        out += `<a href="${escapeAttribute(link.url)}">${renderInline(link.inner, definitions)}</a>`
        index = link.next
        continue
      }
    }
    out += escapeText(character)
    index += 1
  }
  return out
}
"}

