{"file_path":"src/block.js","content":"/** Block parsing: fences, headings, link definitions, nested lists, and paragraphs. */

import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { matchDefinition } from './links.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * The blocks of one document, recording every link definition it carries.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, {url: string, source: string}>} [definitions] - the definitions in force, extended in place.
 * @returns {object[]} the blocks in document order.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, definitions = new Map()) {
  const out = []
  let paragraph = []
  let items
  let path = []
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (items !== undefined) {
      out.push({ kind: 'list', items })
      items = undefined
      path = []
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    if (raw.trim() === '') {
      flush()
      continue
    }
    const definition = matchDefinition(raw.trim())
    if (definition !== undefined) {
      flush()
      if (definitions.has(definition.label)) throw new BlockError(line, `label ${definition.label} is defined twice`)
      definitions.set(definition.label, { url: definition.url, source: 'document' })
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (items === undefined) {
        items = []
        path = []
      }
      const level = Math.min(Math.floor(item[1].length / 2), path.length)
      const node = { text: item[2].trim(), children: [] }
      if (level === 0) items.push(node)
      else path[level - 1].children.push(node)
      path.length = level
      path.push(node)
      continue
    }
    if (items !== undefined) flush()
    paragraph.push(raw.trim())
  }
  flush()
