{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/** The command: `html`, `outline`, and `defs`, each over the document on standard input. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { matchDefinition } from './links.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'
const MODES = ['html', 'outline', 'defs']

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every definition one definitions file holds, in the order it writes them. */
function readDefinitions(path, definitions) {
  let text
  try {
    text = readFileSync(path, 'utf8')
  } catch {
    fail(`cannot read definitions ${path}`)
    return
  }
  const lines = splitLines(text)
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim()
    if (line === '' || line.startsWith('#')) continue
    const definition = matchDefinition(line)
    if (definition === undefined) fail(`${path}: line ${index + 1}: expected [label]: <url>`)
    if (definitions.has(definition.label)) fail(`${path}: line ${index + 1}: label ${definition.label} is defined twice`)
    definitions.set(definition.label, { url: definition.url, source: 'file' })
  }
}

const argv = process.argv.slice(2)
const mode = argv[0]
if (!MODES.includes(mode) || argv.length > 2) fail(USAGE)

const definitions = new Map()
if (argv.length === 2) readDefinitions(argv[1], definitions)

let parsed
try {
  parsed = parse(splitLines(readFileSync(0, 'utf8')), definitions)
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(parsed, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(parsed).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const labels = [...definitions.keys()].sort()
  const listed = labels.map(label => `${label} ${definitions.get(label).url} ${definitions.get(label).source}\n`)
  process.stdout.write(`${listed.join('')}total ${labels.length}\n`)
}
"}

